scripts.factorial_mod:
def solve(inputs: dict) -> float:
    n = int(inputs['N'])
    mod = int(inputs['MOD'])
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % mod
    return float(result)

scripts.luhn_sum:
def solve(inputs: dict) -> float:
    n_str = str(int(inputs['N']))
    total = 0
    # Double every 2nd digit from the right (positions 2, 4, 6, ... from right)
    # rightmost is position 1 (odd), not doubled
    for i, digit in enumerate(reversed(n_str)):
        d = int(digit)
        if (i + 1) % 2 == 0:  # every 2nd from right
            d *= 2
            if d > 9:
                d -= 9  # cast out nines (same as summing digits)
        total += d
    return float(total)

scripts.gcd_list:
from math import gcd
from functools import reduce

def solve(inputs: dict) -> float:
    # Accept values as a list encoded in inputs, or hardcode for current problem
    # Use inputs dict with keys v0, v1, v2, ... or a direct list
    if 'v0' in inputs:
        values = [int(inputs[f'v{i}']) for i in range(int(inputs['count']))]
    else:
        # fallback hardcoded
        values = [77236640, 162081285, 115387780, 206187905, 148606550, 93118630, 198256140]
    result = reduce(gcd, values)
    return float(result)

scripts.lcg:
def solve(inputs: dict) -> float:
    x = int(inputs['SEED'])
    a = int(inputs['A'])
    b = int(inputs['B'])
    m = int(inputs['M'])
    k = int(inputs['K'])
    for _ in range(k):
        x = (a * x + b) % m
    return float(x)

